package com.airdata.maintenance.model;

import java.awt.Color;

/**
 * Prioritization levels generated by the Intelligent Maintenance Scheduling Engine.
 */
public enum MaintenancePriority {
    ROUTINE("Routine Line Check", "Next 30 Days", new Color(100, 116, 139), "#64748b", 1),
    MEDIUM("Elevated Maintenance", "Next 7 Days", new Color(59, 130, 246), "#3b82f6", 2),
    HIGH("Priority Inspection", "Within 48 Hours", new Color(249, 115, 22), "#f97316", 3),
    URGENT_AOG("Urgent (AOG Warning)", "Within 12-24 Hours", new Color(239, 68, 68), "#ef4444", 4);

    private final String title;
    private final String timeframe;
    private final Color badgeColor;
    private final String hexColor;
    private final int rank;

    MaintenancePriority(String title, String timeframe, Color badgeColor, String hexColor, int rank) {
        this.title = title;
        this.timeframe = timeframe;
        this.badgeColor = badgeColor;
        this.hexColor = hexColor;
        this.rank = rank;
    }

    public String getTitle() { return title; }
    public String getTimeframe() { return timeframe; }
    public Color getBadgeColor() { return badgeColor; }
    public String getHexColor() { return hexColor; }
    public int getRank() { return rank; }
}
